#include <iostream>
#include <string>
#include <pandoc/include/pandoc/include.h>

std::string convertMarkdownToHtml(const std::string& markdown) {
    // Set up Pandoc options
    pandoc::Options options;
    options.input_format = "markdown";
    options.output_format = "html5";
    options.output_file = "";

    // Convert Markdown to HTML
    pandoc::Result<pandoc::Document> result = pandoc::read_string(markdown, options);
    if (!result.is_ok()) {
        throw std::runtime_error(result.error().message());
    }
    pandoc::Document doc = result.value();
    std::string html = pandoc::write_string(doc, options);

    return html;
}

int main() {
    std::string markdown = "Hello **world**!";
    std::string html = convertMarkdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

